        ListNode tail = dummy;
        ListNode curr = head.next;
        int curSum = 0;
        while (curr != null) {
            if (curr.val == 0) {
                tail.next = new ListNode(curSum);
                tail = tail.next;
                curSum = 0;
            } else {
                curSum += curr.val;
